import express, { Express } from "express";
import { AssignTaskUseCase } from "../application/assign-task-use-case";
import { CompleteTaskUseCase } from "../application/complete-task-use-case";
import { CreateProjectUseCase } from "../application/create-project-use-case";
import { CreateTaskUseCase } from "../application/create-task-use-case";
import { CreateUserUseCase } from "../application/create-user-use-case";
import { ListTasksUseCase } from "../application/list-tasks-use-case";
import { asyncHandler } from "./async-handler";
import { errorMiddleware } from "./error-middleware";
import { InMemoryProjectRepository } from "./in-memory-project-repository";
import { InMemoryTaskRepository } from "./in-memory-task-repository";
import { InMemoryUserRepository } from "./in-memory-user-repository";
import { ProjectController } from "./project-controller";
import { TaskController } from "./task-controller";
import { UserController } from "./user-controller";
import { UuidIdGenerator } from "./uuid-id-generator";

export function createApp(): Express {
  const ids = new UuidIdGenerator();
  const users = new InMemoryUserRepository();
  const projects = new InMemoryProjectRepository();
  const tasks = new InMemoryTaskRepository();

  const userController = new UserController(new CreateUserUseCase(users, ids));
  const projectController = new ProjectController(new CreateProjectUseCase(projects, ids));
  const taskController = new TaskController(
    new CreateTaskUseCase(tasks, projects, ids),
    new AssignTaskUseCase(tasks, users),
    new ListTasksUseCase(tasks, projects),
    new CompleteTaskUseCase(tasks),
  );

  const app = express();
  app.use(express.json());
  app.post("/users", asyncHandler(userController.create));
  app.post("/projects", asyncHandler(projectController.create));
  app.post("/projects/:projectId/tasks", asyncHandler(taskController.create));
  app.get("/projects/:projectId/tasks", asyncHandler(taskController.list));
  app.put("/tasks/:taskId/assignee", asyncHandler(taskController.assign));
  app.post("/tasks/:taskId/done", asyncHandler(taskController.complete));
  app.use(errorMiddleware);
  return app;
}

