import { Request, Response } from "express";
import { AssignTaskUseCase } from "../application/assign-task-use-case";
import { CompleteTaskUseCase } from "../application/complete-task-use-case";
import { CreateTaskUseCase } from "../application/create-task-use-case";
import { toTaskResponse } from "../application/dtos";
import { ListTasksUseCase } from "../application/list-tasks-use-case";

function queryString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

export class TaskController {
  constructor(
    private readonly createTask: CreateTaskUseCase,
    private readonly assignTask: AssignTaskUseCase,
    private readonly listTasks: ListTasksUseCase,
    private readonly completeTask: CompleteTaskUseCase,
  ) {}

  create = async (req: Request, res: Response): Promise<void> => {
    const body = req.body ?? {};
    const task = await this.createTask.execute({
      projectId: String(req.params.projectId),
      title: body.title,
      description: body.description,
      dueDate: body.dueDate,
      status: body.status,
    });
    res.status(201).json(toTaskResponse(task));
  };

  list = async (req: Request, res: Response): Promise<void> => {
    const tasks = await this.listTasks.execute({
      projectId: String(req.params.projectId),
      status: queryString(req.query.status),
      assigneeId: queryString(req.query.assigneeId),
    });
    res.json(tasks.map(toTaskResponse));
  };

  assign = async (req: Request, res: Response): Promise<void> => {
    const task = await this.assignTask.execute({
      taskId: String(req.params.taskId),
      assigneeId: req.body?.assigneeId,
    });
    res.json(toTaskResponse(task));
  };

  complete = async (req: Request, res: Response): Promise<void> => {
    const task = await this.completeTask.execute(String(req.params.taskId));
    res.json(toTaskResponse(task));
  };
}

